    "rules/transit.json",
    "rules/burst.json",
    "rules/overrides/altmark-logistik.json",
    "rules/overrides/cordoba-health.json",
    "rules/overrides/norrland-grid.json",
    "rules/overrides/vantage-media.json",
]

def check_keys_sorted(obj, path="$"):
    issues = []
    if isinstance(obj, dict):
        keys = list(obj.keys())
        if keys != sorted(keys):
            issues.append(f"{path}: keys not sorted: {keys}")
        for k, v in obj.items():
            issues.extend(check_keys_sorted(v, f"{path}.{k}"))
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            issues.extend(check_keys_sorted(v, f"{path}[{i}]"))
    return issues

# expected values from original (pre-rewrite) content
expected = {
    "rules/starter.json": {
        "base_fee": "45.00", "currency": "EUR", "effective": "2026-07-01",
        "included_units": 5000, "plan": "starter", "rounding": "half-up-4",
