        ],
    },
    "rules/archive.json": {
        "base_fee": "22.00", "currency": "EUR", "effective": "2026-07-01",
        "included_units": 0, "plan": "archive", "rounding": "half-up-4",
        "tiers": [
            {"rate": "0.0007", "upto": 500000},
            {"rate": "0.0004", "upto": None},
        ],
    },
    "rules/transit.json": {
        "base_fee": "95.00", "currency": "EUR", "effective": "2026-07-01",
        "included_units": 10000, "plan": "transit", "rounding": "half-up-4",
        "tiers": [
            {"rate": "0.0052", "upto": 200000},
            {"rate": "0.0033", "upto": None},
        ],
    },
    "rules/burst.json": {
        "base_fee": "310.00", "currency": "EUR", "effective": "2026-07-01",
        "included_units": 0, "plan": "burst", "rounding": "half-up-4",
        "tiers": [
            {"rate": "0.0210", "upto": 50000},
            {"rate": "0.0165", "upto": None},
        ],
