    "rules/overrides/altmark-logistik.json": {
        "addendum": "CA-2024-118", "customer": "altmark-logistik",
        "discount_pct": "12.5", "effective": "2026-07-01", "plan": "growth",
    },
    "rules/overrides/cordoba-health.json": {
