all_ok = True
for f in files:
    text = Path(f).read_text()
    data = json.loads(text)
    issues = check_keys_sorted(data)
    ends_nl = text.endswith("\n")
    indent2 = "    " not in text  # no 4-space
    values_ok = data == expected[f]
    # also check rate/fee strings preserved as strings with trailing digits via raw text
    print(f"== {f} ==")
    print(f"  sorted keys: {not issues}")
    if issues:
        for i in issues: print(f"    {i}")
        all_ok = False
    print(f"  trailing newline: {ends_nl}")
    print(f"  no 4-space indent: {indent2}")
    print(f"  values match expected: {values_ok}")
    if not ends_nl or not indent2 or not values_ok:
        all_ok = False
    if not values_ok:
        print(f"  got: {data}")
        print(f"  exp: {expected[f]}")

print("ALL OK" if all_ok else "ISSUES FOUND")

# show raw bytes of one rate string to confirm quoting preserved
for f in files[:1]:
    print(Path(f).read_text())
