python3 << 'PY'
import json, os
from pathlib import Path

files = [
    "rules/starter.json",
    "rules/growth.json",
    "rules/scale.json",
    "rules/archive.json",
    "rules/transit.json",
    "rules/burst.json",
    "rules/overrides/altmark-logistik.json",
    "rules/overrides/cordoba-health.json",
    "rules/overrides/norrland-grid.json",
    "rules/overrides/vantage-media.json",
]

def check_keys_sorted(obj, path="$"):
    issues = []
    if isinstance(obj, dict):
        keys = list(obj.keys())
        if keys != sorted(keys):
            issues.append(f"{path}: keys not sorted: {keys}")
        for k, v in obj.items():
            issues.extend(check_keys_sorted(v, f"{path}.{k}"))
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            issues.extend(check_keys_sorted(v, f"{path}[{i}]"))
    return issues

# expected values from original (pre-rewrite) content
expected = {
    "rules/starter.json": {
        "base_fee": "45.00", "currency": "EUR", "effective": "2026-07-01",
        "included_units": 5000, "plan": "starter", "rounding": "half-up-4",
        "tiers": [
            {"rate": "0.0140", "upto": 25000},
            {"rate": "0.0115", "upto": 100000},
            {"rate": "0.0090", "upto": None},
        ],
    },
    "rules/growth.json": {
        "base_fee": "180.00", "currency": "EUR", "effective": "2026-07-01",
        "included_units": 50000, "plan": "growth", "rounding": "half-up-4",
        "tiers": [
            {"rate": "0.0085", "upto": 100000},
            {"rate": "0.0062", "upto": 500000},
            {"rate": "0.0041", "upto": None},
        ],
    },
    "rules/scale.json": {
        "base_fee": "640.00", "currency": "EUR", "effective": "2026-07-01",
        "included_units": 250000, "plan": "scale", "rounding": "half-up-4",
        "tiers": [
            {"rate": "0.0038", "upto": 1000000},
            {"rate": "0.0026", "upto": 5000000},
            {"rate": "0.0019", "upto": None},
        ],
    },
    "rules/archive.json": {
        "base_fee": "22.00", "currency": "EUR", "effective": "2026-07-01",
        "included_units": 0, "plan": "archive", "rounding": "half-up-4",
        "tiers": [
            {"rate": "0.0007", "upto": 500000},
            {"rate": "0.0004", "upto": None},
        ],
    },
    "rules/transit.json": {
        "base_fee": "95.00", "currency": "EUR", "effective": "2026-07-01",
        "included_units": 10000, "plan": "transit", "rounding": "half-up-4",
        "tiers": [
            {"rate": "0.0052", "upto": 200000},
            {"rate": "0.0033", "upto": None},
        ],
    },
    "rules/burst.json": {
        "base_fee": "310.00", "currency": "EUR", "effective": "2026-07-01",
        "included_units": 0, "plan": "burst", "rounding": "half-up-4",
        "tiers": [
            {"rate": "0.0210", "upto": 50000},
            {"rate": "0.0165", "upto": None},
        ],
    },
    "rules/overrides/altmark-logistik.json": {
        "addendum": "CA-2024-118", "customer": "altmark-logistik",
        "discount_pct": "12.5", "effective": "2026-07-01", "plan": "growth",
    },
    "rules/overrides/cordoba-health.json": {
        "addendum": "CA-2023-077", "customer": "cordoba-health",
        "discount_pct": "8.0", "effective": "2026-07-01", "plan": "scale",
    },
    "rules/overrides/norrland-grid.json": {
        "addendum": "CA-2025-204", "customer": "norrland-grid",
        "discount_pct": "20.0", "effective": "2026-07-01", "plan": "transit",
    },
    "rules/overrides/vantage-media.json": {
        "addendum": "CA-2026-031", "customer": "vantage-media",
        "discount_pct": "5.0", "effective": "2026-07-01", "plan": "burst",
    },
}

all_ok = True
for f in files:
    text = Path(f).read_text()
    data = json.loads(text)
    issues = check_keys_sorted(data)
    ends_nl = text.endswith("\n")
    indent2 = "    " not in text  # no 4-space
    values_ok = data == expected[f]
    # also check rate/fee strings preserved as strings with trailing digits via raw text
    print(f"== {f} ==")
    print(f"  sorted keys: {not issues}")
    if issues:
        for i in issues: print(f"    {i}")
        all_ok = False
    print(f"  trailing newline: {ends_nl}")
    print(f"  no 4-space indent: {indent2}")
    print(f"  values match expected: {values_ok}")
    if not ends_nl or not indent2 or not values_ok:
        all_ok = False
    if not values_ok:
        print(f"  got: {data}")
        print(f"  exp: {expected[f]}")

print("ALL OK" if all_ok else "ISSUES FOUND")

# show raw bytes of one rate string to confirm quoting preserved
for f in files[:1]:
    print(Path(f).read_text())
PY

